            erp.components[r["component_id"]][r["field"]] = r["new"]
    erp.snapshot = max((str(r.get("snapshot_date") or "") for r in erp.stock), default="")
    sup_root = root / "suppliers"
    for d in sorted(sup_root.iterdir()) if sup_root.is_dir() else []:
        if not d.is_dir():
