"""
Launch alerts in Microsoft Teams, where buyers already work (Lio's own channel).

Posts an Adaptive Card to a Teams channel through a "Workflows" incoming webhook
(ASK_TEAMS_WEBHOOK; in Teams: Workflows -> "Post to a channel when a webhook request is
received"). The card states the problem and what does not match; its buttons open the decision in
the app (approve, talk it through, evidence), so the decision itself stays in one place with its
audit trail.

- New open inbox cards (red or amber) are posted once by a background loop (ASK_TEAMS=on)
- Supplier replies tied back to a card are posted as a follow-up
- POST /api/teams/test posts one card on demand
"""

import json
import logging
import os
import threading
import time
from urllib.parse import quote

import httpx
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

from ask_soony.config import load_dotenv

log = logging.getLogger("ask_soony.teams")
router = APIRouter()
# The app's colours: red (Attention) only for what misses the trucks, the rest stays quiet.
LEVEL_COLOR = {"red": "Attention", "amber": "Default", "grey": "Default", "blue": "Default"}


def _webhook() -> str:
    load_dotenv()
    return os.environ.get("ASK_TEAMS_WEBHOOK", "").strip()


def _app_url() -> str:
    return (
        os.environ.get("ASK_APP_URL")
        or os.environ.get("ASK_PUSH_CONTACT")
        or os.environ.get("ASK_PUBLIC_URL")
        or ""
    ).rstrip("/")


def _num(n) -> str:
    try:
        return f"{float(n):,.0f}"
    except (TypeError, ValueError):
        return str(n or "")


def card_payload(card: dict, reply: dict | None = None) -> dict:
    """The Teams message for one inbox card (Adaptive Card 1.4)."""
    link = f"{_app_url()}/d/{quote(card['id'])}"
    level = card.get("level") or "amber"
    evidence = card.get("evidence") or []
    system = next((e for e in evidence if "system" in str(e.get("source", "")).lower()), None)
    paper = next(
        (e for e in evidence if e is not system and "paper" in str(e.get("source", "")).lower()),
        None,
    )
    body: list[dict] = [
        {
            "type": "TextBlock",
            "text": (
                "Supplier replied"
                if reply
                else "Launch at risk"
                if level == "red"
                else "Needs a decision"
            ),
            "color": "Default" if reply else LEVEL_COLOR.get(level, "Default"),
            "isSubtle": bool(reply) or level != "red",
            "size": "Small",
        },
        {
            "type": "TextBlock",
            "text": card.get("headline", ""),
            "weight": "Bolder",
            "size": "Large",
            "wrap": True,
        },
    ]
    if reply:
        body.append(
            {
                "type": "TextBlock",
                "wrap": True,
                "text": f"**{reply.get('from', 'Supplier')}:** {reply.get('summary', '')}",
            }
        )
    else:
        facts = []
        if card.get("number"):
            facts.append(
                {"title": card.get("number_label") or "At risk", "value": _num(card["number"])}
            )
        if card.get("deadline"):
            facts.append(
                {"title": "Decide by", "value": str(card["deadline"])[:16].replace("T", " ")}
            )
        if card.get("supplier_name"):
            facts.append({"title": "Supplier", "value": card["supplier_name"]})
        if facts:
            body.append({"type": "FactSet", "facts": facts})
        if system and paper:
            body.append(
                {
                    "type": "ColumnSet",
                    "columns": [
                        {
                            "type": "Column",
                            "width": "stretch",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "The system says",
                                    "size": "Small",
                                    "isSubtle": True,
                                },
                                {
                                    "type": "TextBlock",
                                    "text": str(system.get("value", "")),
                                    "weight": "Bolder",
                                    "wrap": True,
                                },
                            ],
                        },
                        {
                            "type": "Column",
                            "width": "stretch",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "The document says",
                                    "size": "Small",
                                    "isSubtle": True,
                                },
                                {
                                    "type": "TextBlock",
                                    "text": str(paper.get("value", "")),
                                    "weight": "Bolder",
                                    "wrap": True,
                                    "color": LEVEL_COLOR.get(level, "Default"),
                                },
                            ],
                        },
                    ],
                }
            )
        rec = next((o for o in card.get("options") or [] if o.get("recommended")), None)
        if rec:
            body.append(
                {
                    "type": "TextBlock",
                    "wrap": True,
                    "spacing": "Medium",
                    "text": f"**We recommend:** {rec.get('action', '')}"
                    + (f" · {rec['cost']}" if rec.get("cost") else ""),
                }
            )
    actions = [
        {"type": "Action.OpenUrl", "title": "Review and approve", "url": link},
        {"type": "Action.OpenUrl", "title": "Talk it through", "url": f"{link}?talk=1"},
    ]
    return {
        "type": "message",
        "attachments": [
            {
                "contentType": "application/vnd.microsoft.card.adaptive",
                "contentUrl": None,
                "content": {
                    "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
                    "type": "AdaptiveCard",
                    "version": "1.4",
                    "msteams": {"width": "Full"},
                    "body": body,
                    "actions": actions,
                },
            }
        ],
    }


def post(card: dict, reply: dict | None = None) -> bool:
    url = _webhook()
    if not url:
        return False
    r = httpx.post(url, json=card_payload(card, reply), timeout=20)
    if r.status_code >= 300:
        log.warning("teams post failed: %s %s", r.status_code, r.text[:200])
        return False
    return True


def notify_reply(card_id: str, who: str, summary: str) -> None:
    """Follow-up when a supplier answered (called by the reply poller)."""
    if not _webhook():
        return
    from ask_soony import api

    try:
        post(api._card(card_id), {"from": who, "summary": summary})
    except Exception as exc:  # Teams is a convenience; the reply is on the card anyway
        log.warning("teams reply post failed: %s", exc)


def check_once() -> list[str]:
    """Post open inbox cards (red or amber) that were not posted yet."""
    if not _webhook():
        return []
    from ask_soony import api

    state = api.build_state()
    seen = set(api.read_json("teams_posted.json", []))
    first_run = not (api.state_dir() / "teams_posted.json").exists()
    posted = []
    for card in state["cards"]:
        if card["id"] in seen or card["id"] not in state["inbox_ids"]:
            continue
        if card.get("level") not in ("red", "amber"):
            continue
        # The first run only remembers what is already there (no flood when switching it on),
        # unless ASK_TEAMS_BACKFILL=on.
        if first_run and os.environ.get("ASK_TEAMS_BACKFILL", "").lower() not in ("1", "on"):
            seen.add(card["id"])
            continue
        if post(card):
            seen.add(card["id"])
            posted.append(card["id"])
    api.write_json("teams_posted.json", sorted(seen))
    return posted


def _loop(interval: int) -> None:
    while True:
        try:
            for cid in check_once():
                log.info("posted %s to Teams", cid)
        except Exception as exc:
            log.warning("teams check failed: %s", exc)
        time.sleep(interval)


def start_background() -> None:
    # Process environment only, like ASK_BACKGROUND: loading .env at import time would pull its
    # secrets into every process that imports the app, tests included.
    if os.environ.get("ASK_TEAMS", "").lower() not in ("1", "on", "true", "yes"):
        return
    interval = int(os.environ.get("ASK_TEAMS_POLL_SECONDS", "60"))
    threading.Thread(target=_loop, args=(interval,), daemon=True, name="teams").start()


class TestPost(BaseModel):
    card_id: str | None = None


@router.post("/api/teams/test")
def teams_test(body: TestPost):
    from ask_soony import api

    if not _webhook():
        raise HTTPException(409, "ASK_TEAMS_WEBHOOK is not set")
    state = api.build_state()
    card = next((c for c in state["cards"] if c["id"] == body.card_id), None) or next(
        (c for c in state["cards"] if c["id"] in state["inbox_ids"]), None
    )
    if card is None:
        raise HTTPException(404, "no card to post")
    if not post(card):
        raise HTTPException(502, "Teams refused the post (see the server log)")
    return {"posted": card["id"]}


def preview(card: dict) -> str:
    """The card JSON, for pasting into the Adaptive Card designer."""
    return json.dumps(card_payload(card)["attachments"][0]["content"], indent=2)
"""
Web push for the installed dashboard (PWA): a critical card rings the phone with a notification;
tapping it opens the card with an "Answer" button that starts the voice conversation.

VAPID keys are generated once and kept in data/state/vapid.json (gitignored with data/).
Subscriptions are kept in data/state/push_subscriptions.json.
"""

import base64
import json
import os
from pathlib import Path

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import ec
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

router = APIRouter()


def _state_dir() -> Path:
    return Path(os.environ.get("ASK_STATE_DIR", "data/state"))


def _b64url(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()


def vapid() -> dict:
    """Load or create the VAPID key pair: PEM private key path and the public key for browsers."""
    path = _state_dir() / "vapid.json"
    pem = _state_dir() / "vapid_private.pem"
    if path.exists() and pem.exists():
        return json.loads(path.read_text())
    pem.parent.mkdir(parents=True, exist_ok=True)
    key = ec.generate_private_key(ec.SECP256R1())
    pem.write_bytes(
        key.private_bytes(
            serialization.Encoding.PEM,
            serialization.PrivateFormat.PKCS8,
            serialization.NoEncryption(),
        )
    )
    os.chmod(pem, 0o600)
    public = key.public_key().public_bytes(
        serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint
    )
    data = {"public_key": _b64url(public), "private_pem": str(pem)}
    path.write_text(json.dumps(data))
    return data


def _subs_path() -> Path:
    return _state_dir() / "push_subscriptions.json"


def subscriptions() -> list[dict]:
    try:
        return json.loads(_subs_path().read_text())
    except (OSError, ValueError):
        return []


def send(title: str, body: str, card_id: str | None = None) -> dict:
    """Push to every subscribed device; drop subscriptions the push service reports as gone."""
    from pywebpush import WebPushException, webpush

    keys = vapid()
    claims_sub = os.environ.get("ASK_PUSH_CONTACT", "https://ask-soony.example.com")
    payload = json.dumps({"title": title, "body": body, "card_id": card_id})
    kept, sent, failed = [], 0, []
    for sub in subscriptions():
        try:
            webpush(
                sub,
                payload,
                vapid_private_key=REDACTED,
                vapid_claims={"sub": claims_sub},
                ttl=600,
            )
            kept.append(sub)
            sent += 1
        except WebPushException as e:
            status = getattr(e.response, "status_code", None)
            if status not in (404, 410):  # 404/410: subscription expired, forget it
                kept.append(sub)
            failed.append(str(status or e)[:120])
    _subs_path().write_text(json.dumps(kept))
    return {"sent": sent, "failed": failed}


@router.get("/api/push/key")
def push_key():
    return {"public_key": vapid()["public_key"]}


class Subscription(BaseModel):
    endpoint: str
    keys: dict


@router.post("/api/push/subscribe")
def push_subscribe(sub: Subscription):
    subs = [s for s in subscriptions() if s.get("endpoint") != sub.endpoint]
    subs.append(sub.model_dump())
    _subs_path().parent.mkdir(parents=True, exist_ok=True)
    _subs_path().write_text(json.dumps(subs))
    return {"devices": len(subs)}


class TestPush(BaseModel):
    card_id: str | None = None


@router.post("/api/push/test")
def push_test(body: TestPush):
    from ask_soony import api  # late import: api includes this router

    state = api.build_state()
    cards = state["cards"]
    inbox = [c for c in cards if c["id"] in state["inbox_ids"]]
    card = next((c for c in cards if c.get("id") == body.card_id), None) or (
        inbox[0] if inbox else None
    )
    if not subscriptions():
        raise HTTPException(409, "no device has enabled alerts yet")
    if card is None:
        return send("Ask Soony", "Test alert: alerts are on for this device.", None)
    return send(decision_title(card), card["headline"], card["id"])


def decision_title(card: dict) -> str:
    """'One decision before 10:00' (local time), or plain 'One decision' without a deadline."""
    from ask_soony import api

    deadline = api.parse_ts(card.get("deadline"))
    if deadline is None:
        return "One decision for you"
    return f"One decision before {deadline.astimezone(api.tz()).strftime('%H:%M')}"
"""
Optional password protection for the dashboard API when it is exposed (for example through a
tunnel to test on a phone). Active only when ASK_DASHBOARD_PASSWORD is set in the process
environment at startup (not read from .env, so local runs and tests stay open).

Two ways in: HTTP basic auth (curl, scripts; any user name) or the /login form, which sets a
long-lived cookie. The cookie is needed for home screen apps on iOS: they show no basic auth
dialog and do not keep basic auth credentials, so a reopened app would get a blank 401 page.
"""

import base64
import hashlib
import hmac
import html
import os
from urllib.parse import parse_qs, quote

from starlette.middleware.base import BaseHTTPMiddleware
from starlette.requests import Request
from starlette.responses import HTMLResponse, RedirectResponse, Response

# Static PWA files hold no data; browsers (notably iOS) fetch the manifest without credentials,
# and without it the page is not installable and cannot ask for notification permission.
PUBLIC_PATHS = {"/manifest.webmanifest", "/sw.js", "/icon-192.png", "/icon-512.png", "/favicon.svg"}
COOKIE = "ask_session"
COOKIE_DAYS = 30

LOGIN_PAGE = """<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#fbfbfa"><title>Ask Soony</title>
<link rel="icon" type="image/svg+xml" href="/favicon.svg">
<link rel="stylesheet"
href="https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600&display=swap">
<style>*{{box-sizing:border-box}}body{{margin:0;min-height:100vh;display:grid;place-items:center;
background:#fbfbfa;color:#18181a;-webkit-font-smoothing:antialiased;
font-family:"Instrument Sans",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}}
form{{width:min(340px,calc(100vw - 48px));padding-bottom:12vh}}svg{{display:block}}
h1{{margin:28px 0 0;font-size:27px;line-height:1.2;font-weight:600;letter-spacing:-.025em}}
p{{margin:10px 0 0;font-size:15px;line-height:1.5;color:#5d5d63}}
input,button{{width:100%;height:52px;font:inherit;font-size:17px;border:0;border-radius:14px}}
input{{margin-top:32px;padding:0 16px;background:#f3f3f1;color:#18181a}}
input:focus,button:focus-visible{{outline:2px solid #2348d0;outline-offset:2px}}
button{{margin-top:12px;background:#2348d0;color:#fff;font-weight:500;cursor:pointer;
box-shadow:0 1px 2px rgba(35,72,208,.25)}}button:hover{{background:#1d3db5}}
.err{{color:#c8321f}}</style></head><body>
<form method="post" action="/login">
<svg width="28" height="28" viewBox="0 0 24 24" aria-hidden="true"><path
d="M2.5 8V2.5H8M16 2.5h5.5V8M21.5 16v5.5H16M8 21.5H2.5V16" fill="none" stroke="#18181a"
stroke-width="2.4" stroke-linecap="square"/><rect x="6.5" y="9.5" width="11" height="5" rx="1"
fill="#ffe066"/></svg>
<h1>Ask Soony</h1><p>Sign in to see what needs you today.</p>{error}
<input type="hidden" name="next" value="{next}">
<input type="password" name="password" placeholder="Password" aria-label="Password" autofocus
autocomplete="current-password">
<button>Sign in</button></form></body></html>"""


class BasicAuth(BaseHTTPMiddleware):
    def __init__(self, app):
        super().__init__(app)
        self.password = os.environ.get("ASK_DASHBOARD_PASSWORD", "")
        self.token = REDACTED
            self.password.encode(), b"ask-soony-session", hashlib.sha256
        ).hexdigest()

    def _basic_ok(self, request: Request) -> bool:
        header = request.headers.get("authorization", "")
        if not header.startswith("Basic "):
            return False
        try:
            _, _, pw = base64.b64decode(header[6:]).decode().partition(":")
        except ValueError:
            return False
        return hmac.compare_digest(pw, self.password)

    def _cookie_ok(self, request: Request) -> bool:
        return hmac.compare_digest(request.cookies.get(COOKIE, ""), self.token)

    def _login_page(self, next_url: str, error: str = "", status: int = 200) -> HTMLResponse:
        err = f'<p class="err">{error}</p>' if error else ""
        page = LOGIN_PAGE.format(error=err, next=html.escape(next_url, quote=True))
        return HTMLResponse(page, status_code=status)

    async def dispatch(self, request: Request, call_next):
        path = request.url.path
        # Call webhooks authenticate themselves (signature or per-alert token), see calls.py.
        if not self.password or path in PUBLIC_PATHS or path.startswith("/hooks/"):
            return await call_next(request)

        if path == "/login":
            if request.method == "POST":
                raw = parse_qs((await request.body()).decode(errors="replace"))
                form = {k: v[0] for k, v in raw.items()}
                next_url = str(form.get("next") or "/")
                if not next_url.startswith("/") or next_url.startswith("//"):
                    next_url = "/"
                if hmac.compare_digest(str(form.get("password") or ""), self.password):
                    resp = RedirectResponse(next_url, status_code=303)
                    resp.set_cookie(
                        COOKIE,
                        self.token,
                        max_age=COOKIE_DAYS * 86400,
                        httponly=True,
                        secure=True,
                        samesite="lax",
                    )
                    return resp
                return self._login_page(next_url, "Wrong password.", 401)
            return self._login_page(request.query_params.get("next", "/"))

        if self._cookie_ok(request) or self._basic_ok(request):
            return await call_next(request)

        # Pages go to the login form (keeps ?card=..&talk=1 from a push); API calls get 401.
        if request.method == "GET" and not path.startswith("/api/"):
            target = path + (f"?{request.url.query}" if request.url.query else "")
            login = RedirectResponse(f"/login?next={quote(target, safe='/')}", status_code=303)
            login.headers["Cache-Control"] = "no-store"
            return login
        return Response(status_code=401, headers={"WWW-Authenticate": 'Basic realm="ask-soony"'})

