        self.lines: list[str] = []
        self.did: list[dict] = []
        self.state = state if state is not None else api.build_state()
        self.cur = api.now()
        self.cards = [
            c
            for c in self.state["cards"]
            if c["id"] in self.state["inbox_ids"] and c["status"] == "open"
